<?php

declare(strict_types=1);

namespace App\Infrastructure\Persistence\Sqlite;

use App\Domain\Entity\Banner;
use App\Domain\Port\Outbound\BannerRepositoryPort;
use PDO;

/**
 * Driven SQLite Adapter generated by Tuzygent Hexagonal Harness
 */
final readonly class SqliteBannerRepository implements BannerRepositoryPort
{
    public function __construct(
        private PDO $pdo
    ) {
        $this->pdo->exec('
            CREATE TABLE IF NOT EXISTS banners (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                code TEXT NOT NULL,
                is_active INTEGER NOT NULL DEFAULT 1,
                created_at TEXT NOT NULL
            )
        ');
    }

    public function findAll(): array
    {
        $stmt = $this->pdo->query('SELECT * FROM banners ORDER BY id DESC');
        $rows = $stmt ? $stmt->fetchAll() : [];
        return array_map(fn(array $r) => new Banner(
            id: (int) $r['id'],
            name: (string) $r['name'],
            code: (string) $r['code'],
            isActive: (bool) ((int) $r['is_active']),
            createdAt: (string) $r['created_at']
        ), $rows);
    }

    public function findById(int $id): ?Banner
    {
        $stmt = $this->pdo->prepare('SELECT * FROM banners WHERE id = ? LIMIT 1');
        $stmt->execute([$id]);
        $r = $stmt->fetch();
        if (!$r) {
            return null;
        }
        return new Banner(
            id: (int) $r['id'],
            name: (string) $r['name'],
            code: (string) $r['code'],
            isActive: (bool) ((int) $r['is_active']),
            createdAt: (string) $r['created_at']
        );
    }

    public function save(Banner $entity): int
    {
        $now = date('Y-m-d H:i:s');
        if ($entity->id === null) {
            $stmt = $this->pdo->prepare('INSERT INTO banners (name, code, is_active, created_at) VALUES (?, ?, ?, ?)');
            $stmt->execute([$entity->name, $entity->code, $entity->isActive ? 1 : 0, $now]);
            return (int) $this->pdo->lastInsertId();
        }
        $stmt = $this->pdo->prepare('UPDATE banners SET name = ?, code = ?, is_active = ? WHERE id = ?');
        $stmt->execute([$entity->name, $entity->code, $entity->isActive ? 1 : 0, $entity->id]);
        return $entity->id;
    }

    public function delete(int $id): void
    {
        $stmt = $this->pdo->prepare('DELETE FROM banners WHERE id = ?');
        $stmt->execute([$id]);
    }
}
